/* Pure, deterministic effect evaluation + shared browser renderer. */
function createPaperEffects(){
 const types={scale:{name:'缩放',min:10,max:400,unit:'%'},move:{name:'移动',min:-200,max:200,unit:'舞台 %'},opacity:{name:'淡入 / 淡出',min:0,max:100,unit:'%'},blur:{name:'模糊',min:0,max:40,unit:'px / 1280画布'},brightness:{name:'亮度',min:0,max:250,unit:'%'},contrast:{name:'对比度',min:0,max:250,unit:'%'},saturation:{name:'饱和度',min:0,max:250,unit:'%'},rotate:{name:'旋转',min:-180,max:180,unit:'°'}};
 const neutral=()=>({scale:100,x:0,y:0,opacity:100,blur:0,brightness:100,contrast:100,saturation:100,rotate:0,originX:50,originY:50});
 const keys=t=>t==='move'?['x','y']:[t];
 function before(p,C,id,trail){const current=p.nodes.find(n=>n.id===id);let state={};const route=trail||p.nodes.slice(0,p.nodes.indexOf(current)).map(n=>n.id);for(const nid of route){const n=p.nodes.find(n=>n.id===nid);if(!n)continue;if(n.sceneMode==='own')state={};for(const e of n.effects||[]){if(!e.enabled||e.policy!=='hold')continue;const s=state[e.layer]||neutral();if(e.type==='move'){s.x=e.to;s.y=e.toY}else s[e.type]=e.to;if(e.type==='scale'||e.type==='rotate'){s.originX=e.originX;s.originY=e.originY}state[e.layer]=s}}if(current?.sceneMode==='own')state={};return state}
 const ease=(t,kind)=>kind==='linear'?t:kind==='in'?t*t:kind==='out'?1-(1-t)*(1-t):t*t*(3-2*t);
 function span(e){return e.delay+e.duration+(e.policy==='auto'?e.returnDuration:0)}
 function duration(n){return Math.max(0,...(n?.effects||[]).filter(e=>e.enabled).map(span))}
 function frame(p,C,id,trail,seconds=Infinity,inherited){const state=inherited?Object.fromEntries(Object.entries(inherited).map(([k,v])=>[k,{...v}])):before(p,C,id,trail),n=p.nodes.find(n=>n.id===id);for(const e of n?.effects||[]){if(!e.enabled)continue;const s=state[e.layer]||neutral();const starts=keys(e.type).map((k,i)=>i?(e.fromY??s[k]):(e.from??s[k]));const ends=e.type==='move'?[e.to,e.toY]:[e.to];const t=seconds-e.delay;let ratio=t<0?0:e.duration===0?1:Math.min(1,t/e.duration);ratio=ease(ratio,e.easing);if(e.policy==='auto'&&t>=e.duration){const r=e.returnDuration===0?1:Math.min(1,(t-e.duration)/e.returnDuration);ratio=1-ease(r,e.easing)}keys(e.type).forEach((k,i)=>s[k]=starts[i]+(ends[i]-starts[i])*ratio);if(e.type==='scale'||e.type==='rotate'){s.originX=e.originX;s.originY=e.originY}state[e.layer]=s}return state}
 function validate(list){if(!Array.isArray(list)||list.length>100)throw Error('演出列表无效');const used=new Set(),ids=new Set();for(const e of list){const t=types[e?.type],num=(x,a,b)=>Number.isFinite(x)&&x>=a&&x<=b;if(!t||typeof e.id!=='string'||ids.has(e.id)||typeof e.layer!=='string'||typeof e.enabled!=='boolean'||!['hold','sentence','auto'].includes(e.policy)||!['linear','smooth','in','out'].includes(e.easing)||!num(e.duration,0,20)||!num(e.delay,0,20)||!num(e.returnDuration,0,20)||!num(e.originX,0,100)||!num(e.originY,0,100)||!(e.from===null||num(e.from,t.min,t.max))||!num(e.to,t.min,t.max)||!(e.fromY===null||num(e.fromY,-200,200))||!num(e.toY,-200,200))throw Error('演出参数无效');ids.add(e.id);const key=e.layer+'/'+e.type;if(used.has(key))throw Error('同一台词同一图层不能重复添加相同效果');used.add(key)}}
 function make(id,layer,type){return {id,layer,type,enabled:true,from:null,to:type==='scale'?120:type==='blur'?8:type==='move'?10:type==='rotate'?5:100,fromY:null,toY:0,duration:.4,delay:0,returnDuration:.4,policy:'sentence',easing:'smooth',originX:50,originY:type==='scale'?25:50}}
 function apply(container,layers,state){const scale=container.getBoundingClientRect().width/1280;for(const wrap of container.children){const l=layers.find(l=>l.id===wrap.dataset.layer);if(!l)continue;const s=state[l.id]||neutral();wrap.style.left=(l.x+s.x)+'%';wrap.style.top=(l.y+s.y)+'%';wrap.style.opacity=(l.opacity/100)*(s.opacity/100);wrap.style.transformOrigin=s.originX+'% '+s.originY+'%';wrap.style.transform='scale('+s.scale/100+') rotate('+s.rotate+'deg)';wrap.style.filter='blur('+s.blur*scale+'px) brightness('+s.brightness+'%) contrast('+s.contrast+'%) saturate('+s.saturation+'%)'}}
 function animate(p,C,id,trail,container,layers,onTime){let raf=0,cancelled=false,start=performance.now();const n=p.nodes.find(n=>n.id===id),base=before(p,C,id,trail),total=duration(n),reduced=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;function tick(now){if(cancelled)return;const time=reduced?total:Math.min(total,(now-start)/1000);apply(container,layers,frame(p,C,id,trail,time,base));onTime?.(time,total);if(time<total)raf=requestAnimationFrame(tick)}tick(start);return ()=>{cancelled=true;cancelAnimationFrame(raf)}}
 return {types,neutral,keys,before,frame,duration,validate,make,apply,animate};
}
if(typeof module!=='undefined')module.exports=createPaperEffects;
